        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }

    function field({ id, label, type, value, required, placeholder, helperText, errorText }) {
      return `
        <div class="form-field">
          <label for="${id}">
            ${label}${required ? '<span class="required">*</span>' : ''}
          </label>
          <input
            id="${id}"
