                <p class="status" aria-live="polite">${submitted && !errors.fullName && !errors.email ? "Thanks — your message is ready to send." : ""}</p>

                <div class="actions">
                  <button type="submit">Submit</button>
                </div>
              </form>
            </div>
          </div>
        </section>
      `;
    }

