      transition: transform 140ms ease, box-shadow 140ms ease, filter 140ms ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 18px 34px rgba(79, 70, 229, 0.36);
      filter: brightness(1.03);
    }

    button:active {
      transform: translateY(0);
    }

    .status {
      margin: 0;
      min-height: 1.4em;
      color: var(--accent-2);
      font-size: 0.95rem;
    }

    @media (max-width: 640px) {
      .card-inner {
        padding: 20px;
      }

      .actions {
        justify-content: stretch;
      }

      button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    const state = {
      submitted: false,
      values: {
        fullName: "",
        email: "",
        phone: ""
      }
    };

    function escapeHtml(value) {
      return String(value)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }

    function field({ id, label, type, value, required, placeholder, helperText, errorText }) {
      return `
        <div class="form-field">
          <label for="${id}">
            ${label}${required ? '<span class="required">*</span>' : ''}
          </label>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            value="${escapeHtml(value)}"
            placeholder="${placeholder}"
            ${required ? "required" : ""}
            aria-describedby="${helperText || errorText ? `${id}-note` : ""}"
          />
          ${helperText ? `<div class="helper-text" id="${id}-note">${helperText}</div>` : ""}
          ${errorText ? `<div class="error-text" id="${id}-note">${errorText}</div>` : ""}
        </div>
      `;
    }

    function SupportForm() {
      const { values, submitted } = state;
      const errors = {
        fullName: submitted && !values.fullName.trim() ? "Please enter your full name." : "",
        email: submitted && !values.email.trim() ? "Please enter your email address." : "",
      };

      return `
        <section class="page-shell">
          <header class="hero">
            <p class="eyebrow">Support</p>
            <h1>Contact our team</h1>
            <p class="subtitle">Send us a message and we’ll get back to you as soon as we can.</p>
          </header>

          <div class="card">
            <div class="card-inner">
              <form class="support-form" novalidate>
                ${field({
                  id: "fullName",
                  label: "Full name",
                  type: "text",
                  value: values.fullName,
                  required: true,
                  placeholder: "Jane Doe",
                  errorText: errors.fullName
                })}
                ${field({
                  id: "email",
                  label: "Email address",
                  type: "email",
                  value: values.email,
                  required: true,
                  placeholder: "jane@example.com",
                  errorText: errors.email
                })}
                ${field({
                  id: "phone",
                  label: "Phone number",
                  type: "tel",
                  value: values.phone,
                  required: false,
                  placeholder: "(555) 123-4567",
                  helperText: "Optional. Use a number we can reach you on, such as +1 (555) 123-4567."
                })}

                <p class="status" aria-live="polite">${submitted && !errors.fullName && !errors.email ? "Thanks — your message is ready to send." : ""}</p>

                <div class="actions">
                  <button type="submit">Submit</button>
                </div>
              </form>
            </div>
          </div>
        </section>
      `;
    }

    function render() {
      document.getElementById("app").innerHTML = SupportForm();

      const form = document.querySelector(".support-form");
      form.addEventListener("submit", (event) => {
        event.preventDefault();
        state.submitted = true;
        render();
      });

      form.querySelectorAll("input").forEach((input) => {
        input.addEventListener("input", (event) => {
          state.values[event.target.name] = event.target.value;
        });
      });
    }

    render();
  </script>
</body>
</html>
